import XCTest
@testable import MosimoCore

/// hazard §8 / importer §3: whether a re-post is an authorized importer's is decided from the post's own chain and the
/// local trust config, so the same post gives the same answer whether it came from the relay or over the mesh.
/// hazard-import.json is the Android fixture (generated by the BSAF publisher code with throwaway keys), read in place.
final class HazardImportTests: XCTestCase {
    private var f: Json!
    private var config: PublicIngress.Config!

    override func setUpWithError() throws {
        f = try fixture("apps/android/bundle-core/src/test/resources/hazard-import.json")
        config = try PublicIngress.config(f["config"]!.serialized)
    }

    private func event(_ name: String) throws -> NostrEvent { try NostrEvent.fromJson(f[name]!) }
    private func view(_ e: NostrEvent, selected: Set<PublicIngress.Selection>? = nil) throws -> PublicIngress.ChainView {
        let now = Instant(epochSecond: e.createdAt + 60)
        return try XCTUnwrap(PublicIngress.chainView(e, roots: config.roots, revocations: PublicIngress.RevocationStore(), now: now, seenAt: now,
                                                     selected: selected ?? config.selected))
    }

    func testAuthorizedImporterIsRecognizedFromThePostAlone() throws {
        let trusted = try event("trusted")
        let v = try view(trusted)
        XCTAssertTrue(v.confirmedNow && v.importAuthorized)
        // Same verdict as the relay ingress check, which additionally requires a live delivery deadline.
        XCTAssertNotNil(PublicIngress.verify(trusted, config, PublicIngress.RevocationStore(), Instant(epochSecond: trusted.createdAt + 60)).receipt)
    }

    func testTrustChoicesSwitchAndAddRoots() throws {
        let testRoot = "fcf986bb79a0527e4b6af50ae8bc32dde9ae81c189b06614a6a1fe3c44bca2ff"
        let test = try PublicIngress.config(#"{"roots":[{"pubkey":"\#(testRoot)","name":"t","roles":["attest","import"],"maxDepth":2,"enabled":true}],"selected":[]}"#)
        XCTAssertEqual(config.roots.count, 1)
        let builtinKey = config.roots[0].pubkeyHex
        let userKey = "3b92115866d54bb1799529ac39312bcd60bbfc1f5235b5785f4f7db748c62510"
        let choices = PublicIngress.TrustChoices(disabled: [builtinKey], added: [.init(pubkey: userKey, name: "追加"), .init(pubkey: "not-a-key", name: "bad")])
        let (effective, entries) = PublicIngress.effective(config, test, PublicIngress.TrustChoices.parse(choices.toJson()))
        XCTAssertEqual(entries.map(\.origin), [.builtin, .test, .user])
        XCTAssertEqual(effective.roots.map(\.enabled), [false, true, true])
        XCTAssertEqual(effective.selected, config.selected)
        // A switched-off root no longer authorizes; switching it back restores the verdict.
        let trusted = try event("trusted")
        let now = Instant(epochSecond: trusted.createdAt + 60)
        XCTAssertEqual(PublicIngress.chainView(trusted, roots: effective.roots, revocations: PublicIngress.RevocationStore(), now: now, seenAt: now,
                                               selected: effective.selected)?.confirmedNow, false)
        XCTAssertNil(PublicIngress.rootKey("xyz"))
        XCTAssertEqual(PublicIngress.TrustChoices(), PublicIngress.TrustChoices.parse("{broken"))
    }

    func testUntrustedOrUnselectedIsNotAuthorized() throws {
        XCTAssertFalse(try view(try event("untrusted")).importAuthorized)
        XCTAssertFalse(try view(try event("trusted"), selected: []).importAuthorized)
        // No usable clock: never confirmed.
        let trusted = try event("trusted")
        XCTAssertEqual(PublicIngress.chainView(trusted, roots: config.roots, revocations: PublicIngress.RevocationStore(), now: nil,
                                               seenAt: Instant(epochSecond: trusted.createdAt), selected: config.selected)?.confirmedNow, false)
    }
}
